// Fleet Standing Check verdict logic
const webhookJson = $('Webhook — Fleet Standing Check').first().json;
const body = webhookJson.body || webhookJson;
const boxName = (body.boxName || '').trim();
const action = (body.action || 'escalate');
const ticketId = (body.ticketId || '');

const nowUtc = new Date();
const yyyy = nowUtc.getUTCFullYear();
const mm = String(nowUtc.getUTCMonth()+1).padStart(2, '0');
const dd = String(nowUtc.getUTCDate()).padStart(2, '0');
const day_key = boxName + '|' + yyyy + '-' + mm + '-' + dd;
const requested_at = nowUtc.toISOString();

const inputItems = $input.all();
const lookupErrored = inputItems.length > 0 && inputItems[0].json && inputItems[0].json.error;
const rows = lookupErrored ? [] : inputItems.map((i) => i.json).filter((r) => r && typeof r === 'object' && Object.keys(r).length > 0);

// Default outputs
let verdict = 'unmatched';
let reason = '';
let client_message = "I'd normally escalate this to the Rescue Rangers team for you. Before I do — it looks like the account may not be current on payments, so let me confirm with management before I put the request in. I'll come back to you as soon as I hear.";
let good_standing = false;

if (lookupErrored) {
  verdict = 'held';
  reason = 'lookup_error';
} else if (!boxName) {
  verdict = 'unmatched';
  reason = 'missing_or_empty_boxName';
} else if (rows.length === 0) {
  verdict = 'unmatched';
  reason = 'no_record_found';
} else {
  const row = rows[0];
  if (row.good_standing === true) {
    verdict = 'allowed';
    reason = '';
    client_message = '';
    good_standing = true;
  } else if (row.good_standing === false) {
    verdict = 'blocked';
    reason = 'good_standing_is_false';
  } else if (row.good_standing === null || row.good_standing === '' || typeof row.good_standing !== 'boolean') {
    verdict = 'unmatched';
    reason = 'good_standing_null_or_not_boolean';
  }
}

// Assemble response body
const responseBody = {
  ok: verdict === 'allowed',
  good_standing,
  verdict,
  reason,
  client_message,
};

// Prepare ledger row
const ledgerRow = {
  ticket_id: ticketId,
  box_slug: boxName,
  client_label: rows[0]?.client_label || '',
  agent_name: rows[0]?.agent_name || '',
  action,
  verdict,
  reason,
  day_key,
  requested_at,
};

return [{ json: { responseBody, ledgerRow } }];
